function safeMerge(target, src) {
  const out = Object.assign(Object.create(null), target)
  for (const key of Object.keys(src)) {
    if (key === "__proto__" || key === "constructor" || key === "prototype") continue
    out[key] = src[key]
  }
  return out
}
